package io.knowledgebrain.learning;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class ConceptEvidenceStoreIntegrationTest {
 Clock clock=Clock.systemUTC();String trace="c".repeat(32);RoadmapStore roadmaps;LearningStudyStore study;ConceptEvidenceStore store;JdbcTemplate sql;UuidV7 ids=new UuidV7(clock);UUID space,actor,node,note,roadmap;RoadmapStore.Roadmap root;
 @BeforeEach void setup(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();roadmaps=new RoadmapStore(ds,clock);study=new LearningStudyStore(ds,clock,roadmaps);store=new ConceptEvidenceStore(ds,clock,roadmaps);sql=new JdbcTemplate(ds);space=ids.next();actor=ids.next();note=ids.next();root=roadmaps.create(space,actor,"Evidence roadmap","",trace);roadmap=root.roadmapId();root=roadmaps.graph(space,roadmap,actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","Original node","")),List.of()),trace);node=root.nodes().getFirst().nodeId();}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 ConceptEvidenceStore.Input input(){return new ConceptEvidenceStore.Input(node,space,note,1,"Raw <script>memo</script>");}
 ConceptReferenceClient.Reference ref(){return new ConceptReferenceClient.Reference(space,note,space,actor,1,"Original concept","PRIVATE");}
 ConceptEvidenceStore.Evidence link(){return store.record(space,roadmap,actor,key(),input(),trace,this::ref).evidence();}
 void status(int expected,Runnable action){assertEquals(expected,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 int events(UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='concept-evidence' AND aggregateid=?",Integer.class,id);}
 @Test void immutableNotePinLocalAuditIndependentVersionsAndNoAutomaticCompletion(){var e=link();assertEquals(7,e.evidenceId().version());assertEquals("Original concept",e.conceptTitle());assertEquals(root,roadmaps.get(space,roadmap));assertEquals(0,study.progress(space,roadmap,node).version());assertEquals(0,study.summary(space,roadmap).recordedSeconds());var two=store.change(space,roadmap,e.evidenceId(),actor,1,"Corrected",false,trace);assertEquals(2,two.version());assertEquals(two,store.change(space,roadmap,e.evidenceId(),actor,2,"Corrected",false,trace));status(412,()->store.change(space,roadmap,e.evidenceId(),actor,1,"stale",false,trace));assertEquals(e,store.history(space,roadmap,e.evidenceId(),2,5).getFirst().snapshot());assertEquals(2,events(e.evidenceId()));}
 @Test void replayBypassesExternalAvailabilityAndReturnsCurrentEvenAfterRetirement(){var key=key();var e=store.record(space,roadmap,actor,key,input(),trace,this::ref).evidence();store.change(space,roadmap,e.evidenceId(),actor,1,"edit",false,trace);store.change(space,roadmap,e.evidenceId(),actor,2,null,true,trace);roadmaps.metadata(space,roadmap,actor,2,null,null,true,trace);var replay=store.record(space,roadmap,actor,key,input(),trace,()->{fail("No second external check on retry");return null;});assertFalse(replay.created());assertEquals("RETIRED",replay.evidence().state());assertEquals(3,replay.evidence().version());status(409,()->store.record(space,roadmap,actor,key,new ConceptEvidenceStore.Input(node,space,note,2,"different"),trace,this::ref));assertEquals(3,events(e.evidenceId()));assertEquals(e,store.history(space,roadmap,e.evidenceId(),2,5).getFirst().snapshot());}
 @Test void foreignOwnerMismatchFailedOwnerCheckAndDuplicatePinHaveNoPartialWrites(){for(var reference:List.of(new ConceptReferenceClient.Reference(actor,note,space,actor,1,"Wrong space","PRIVATE"),new ConceptReferenceClient.Reference(space,note,space,space,1,"Wrong actor","PRIVATE"),new ConceptReferenceClient.Reference(space,note,space,actor,2,"Wrong version","PRIVATE"),new ConceptReferenceClient.Reference(space,note,actor,actor,1,"Foreign private","PRIVATE")))status(503,()->store.record(space,roadmap,actor,key(),input(),trace,()->reference));status(404,()->store.record(space,roadmap,actor,key(),input(),trace,()->{throw new ResponseStatusException(HttpStatus.NOT_FOUND);}));status(404,()->store.record(actor,roadmap,actor,key(),input(),trace,this::ref));status(404,()->store.record(space,roadmap,actor,key(),new ConceptEvidenceStore.Input(ids.next(),space,note,1,""),trace,this::ref));status(400,()->store.record(space,roadmap,actor,key(),new ConceptEvidenceStore.Input(node,space,note,1,"가".repeat(2731)),trace,this::ref));assertTrue(store.page(space,roadmap,null,20).items().isEmpty());var e=link();status(409,()->store.record(space,roadmap,actor,key(),input(),trace,()->{fail();return null;}));assertEquals(1,events(e.evidenceId()));}
 @Test void concurrentRetryCreatesOneEvidenceAndStaleEditorsNeverOverwrite()throws Exception{String key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return store.record(space,roadmap,actor,key,input(),trace,this::ref);});var b=pool.submit(()->{gate.await();return store.record(space,roadmap,actor,key,input(),trace,this::ref);});var first=a.get();var second=b.get();assertNotEquals(first.created(),second.created());assertEquals(first.evidence(),second.evidence());var e=first.evidence();var gate2=new CyclicBarrier(2);var results=new ArrayList<Future<Integer>>();for(String memo:List.of("a","b"))results.add(pool.submit(()->{gate2.await();try{store.change(space,roadmap,e.evidenceId(),actor,1,memo,false,trace);return 200;}catch(ResponseStatusException ex){return ex.getStatusCode().value();}}));assertEquals(Set.of(200,412),Set.of(results.get(0).get(),results.get(1).get()));assertEquals(2,events(e.evidenceId()));}}
 @Test void retirementPreservesPinsAndHistoryWhileCatalogAndCursorAreBounded(){var all=new ArrayList<ConceptEvidenceStore.Evidence>();for(int i=0;i<22;i++){long v=i+1;all.add(store.record(space,roadmap,actor,key(),new ConceptEvidenceStore.Input(node,space,note,v,"memo"),trace,()->new ConceptReferenceClient.Reference(space,note,space,actor,v,"Title "+v,"PRIVATE")).evidence());}var page=store.page(space,roadmap,null,20);assertEquals(20,page.items().size());assertEquals(2,store.page(space,roadmap,page.nextAfter(),20).items().size());var e=all.getFirst();roadmaps.graph(space,roadmap,actor,2,new RoadmapGraph.Edit(List.of(),List.of()),trace);for(int i=1;i<8;i++)store.change(space,roadmap,e.evidenceId(),actor,i,"Edit "+i,false,trace);assertEquals(e.conceptTitle(),store.get(space,roadmap,e.evidenceId()).conceptTitle());assertEquals(e.nodeTitle(),store.get(space,roadmap,e.evidenceId()).nodeTitle());assertEquals(5,store.history(space,roadmap,e.evidenceId(),Long.MAX_VALUE,5).size());assertEquals(3,store.history(space,roadmap,e.evidenceId(),4,5).size());store.change(space,roadmap,e.evidenceId(),actor,8,null,true,trace);status(404,()->store.get(space,roadmap,e.evidenceId()));assertEquals(21,store.page(space,roadmap,null,100).items().size());assertEquals(e,store.history(space,roadmap,e.evidenceId(),2,5).getFirst().snapshot());status(404,()->store.record(space,roadmap,actor,key(),input(),trace,this::ref));roadmaps.metadata(space,roadmap,actor,3,null,null,true,trace);status(404,()->store.change(space,roadmap,all.getLast().evidenceId(),actor,1,"",false,trace));assertEquals(21,store.page(space,roadmap,null,100).items().size());}
 @Test void publicPinsStayPrivateAndKeepRoadmapProgressIndependent(){UUID publicSpace=ids.next();var value=store.record(space,roadmap,actor,key(),new ConceptEvidenceStore.Input(node,publicSpace,note,6,"Private study of public concept"),trace,()->new ConceptReferenceClient.Reference(space,note,publicSpace,actor,6,"Public concept","PUBLIC")).evidence();assertEquals("PRIVATE",value.visibility());assertEquals("PUBLIC",value.conceptVisibility());assertEquals(publicSpace,value.conceptSpaceId());assertEquals(0,study.progress(space,roadmap,node).version());assertEquals(root,roadmaps.get(space,roadmap));status(404,()->store.get(actor,roadmap,value.evidenceId()));assertEquals(1,events(value.evidenceId()));}
}
